import json
from pathlib import Path
changes={}
def holes(n,key,ps):
 tag=f'{n:03}'
 if n not in changes:changes[n]=json.loads(Path(f'artwork/revision2/annotations/{tag}.json').read_text())
 m=json.loads(Path(f'.cache/gardens-roi/{tag}-{key}.json').read_text())
 target=next(t for t in changes[n]['targets'] if t['id']==key)
 target['holes']=[[[round(m['left']+(x-m['offsetX'])/m['scale'],2),round(m['top']+(y-m['offsetY'])/m['scale'],2)] for x,y in points]for points in ps]
